// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    // accept refunds/payouts so withdraw's transfer to the owner succeeds
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint96).max);

        // fund the (fuzzer-chosen) deposit amount and send it into c's fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // owner (deployer = this test contract) withdraws everything
        c.withdrawAll();

        // RULE: after withdrawAll, the contract holds no ether at all
        assertTrue(address(c).balance == 0);
    }
}
